import{crc32}from'./zip.js';
const LIMIT=32*1024*1024;
class Bytes{constructor(){this.buffer=new Uint8Array(65536);this.length=0;}push(...values){if(this.length+values.length>this.buffer.length){const next=new Uint8Array(Math.max(this.buffer.length*2,this.length+values.length));next.set(this.buffer);this.buffer=next;}this.buffer.set(values,this.length);this.length+=values.length;}slice(){return this.buffer.subarray(0,this.length);}}
function putNumber(out,n){if(!Number.isSafeInteger(n)||n<0)throw Error('Invalid BPS number.');for(;;){const byte=n%128;n=Math.floor(n/128);if(!n){out.push(byte|128);return;}out.push(byte);n--;}}
function appendCRC(out,n){for(let i=0;i<4;i++)out.push(n>>>(i*8)&255);}
export function makeBPS(source,target,metadata=''){if(!source.length||!target.length||source.length>LIMIT||target.length>LIMIT)throw Error('BPS patches support GBA files up to 32 MB.');const out=new Bytes();out.push(66,80,83,49);const meta=new TextEncoder().encode(metadata);putNumber(out,source.length);putNumber(out,target.length);putNumber(out,meta.length);for(const b of meta)out.push(b);let i=0;while(i<target.length){const same=i<source.length&&source[i]===target[i],start=i;while(i<target.length&&(i<source.length&&source[i]===target[i])===same)i++;putNumber(out,(i-start-1)*4+(same?0:1));if(!same)for(let j=start;j<i;j++)out.push(target[j]);}appendCRC(out,crc32(source));appendCRC(out,crc32(target));appendCRC(out,crc32(out.slice()));return out.slice().slice();}
export function applyBPS(source,patch){if(patch.length<16||String.fromCharCode(...patch.subarray(0,4))!=='BPS1')throw Error('Choose a BPS patch.');const v=new DataView(patch.buffer,patch.byteOffset,patch.byteLength),end=patch.length-12;if(crc32(patch.subarray(0,patch.length-4))!==v.getUint32(patch.length-4,true))throw Error('This patch is damaged (checksum mismatch).');let at=4;const number=()=>{let value=0,shift=1;for(let i=0;i<10;i++){if(at>=end)throw Error('The BPS patch is truncated.');const b=patch[at++];value+=(b&127)*shift;if(!Number.isSafeInteger(value))throw Error('The BPS patch has an invalid number.');if(b&128)return value;shift*=128;value+=shift;}throw Error('The BPS number is too large.');};const fromSize=number(),toSize=number(),metaSize=number();if(fromSize!==source.length||crc32(source)!==v.getUint32(end,true))throw Error('This patch needs a different original ROM. No file was changed.');if(!toSize||toSize>LIMIT||metaSize>end-at)throw Error('The BPS output size is invalid.');const metadata=new TextDecoder().decode(patch.subarray(at,at+metaSize));at+=metaSize;const output=new Uint8Array(toSize);let pos=0,sourceRelative=0,targetRelative=0;while(pos<toSize){const data=number(),mode=data%4,len=Math.floor(data/4)+1;if(pos+len>toSize)throw Error('The BPS command exceeds its output.');if(mode===0){if(pos+len>source.length)throw Error('The patch reads outside the source ROM.');output.set(source.subarray(pos,pos+len),pos);pos+=len;}else if(mode===1){if(at+len>end)throw Error('The BPS literal data is truncated.');output.set(patch.subarray(at,at+len),pos);at+=len;pos+=len;}else{const relative=number(),delta=Math.floor(relative/2)*(relative%2?-1:1);if(mode===2){sourceRelative+=delta;if(sourceRelative<0||sourceRelative+len>source.length)throw Error('The patch copies outside the source ROM.');output.set(source.subarray(sourceRelative,sourceRelative+len),pos);sourceRelative+=len;pos+=len;}else{targetRelative+=delta;if(targetRelative<0||targetRelative>=pos)throw Error('The patch copies invalid output data.');for(let i=0;i<len;i++)output[pos++]=output[targetRelative++];}}}if(at!==end||crc32(output)!==v.getUint32(end+4,true))throw Error('The patched ROM failed its checksum.');return{bytes:output,metadata};}
